"""Snapping span times to a payroll step."""

from typing import Iterable, List

from hourglass.models import Span

def _snap(minute: int, step: int) -> int:
    """Nearest multiple of step, with halves rounding up."""
    return (minute + step // 2) // step * step

def _clock(minute: int) -> str:
    return f"{minute // 60:02d}:{minute % 60:02d}"

def round_labels(spans: Iterable[Span], step: int) -> List[str]:
    """Labels such as '09:00-17:15 (8h 15m)' for spans snapped to step."""
    if step <= 0 or 60 % step:
        raise ValueError(f"step must divide an hour evenly: {step}")
    labels = []
    for item in spans:
        snapped = Span(_snap(item.start, step), _snap(item.end, step))
        hours, extra = divmod(snapped.minutes, 60)
        labels.append(
            f"{_clock(snapped.start)}-{_clock(snapped.end)} ({hours}h {extra:02d}m)"
        )
    return labels

