import unittest

from hourglass.rounding import round_labels
from hourglass.models import Span

class RoundLabelTests(unittest.TestCase):
    def test_label_format(self):
        result = round_labels([Span(540, 1035)], 15)
        self.assertEqual(result, ["09:00-17:15 (8h 15m)"])

    def test_snaps_to_nearest_step(self):
        result = round_labels([Span(544, 1028)], 15)
        self.assertEqual(result, ["09:00-17:15 (8h 15m)"])

    def test_bad_steps_raise(self):
        for step in (0, -15, 7):
            with self.assertRaises(ValueError):
                round_labels([Span(540, 600)], step)
